EXCEPTION_SCHEMA = "kind STRING, ref_id STRING, account_id STRING, amount DECIMAL(14,2)"


def reconciliation_exceptions(accounts, transactions, transfers, ledger_entries):
    # Step 6: every unmatched transfer, every entry of an unknown transfer, every account whose balances differ.
    return spark.createDataFrame([], EXCEPTION_SCHEMA)


def reconciliation_summary(accounts, transactions, transfers, ledger_entries):
    # Given: one row per kind of exception, with how many there are and the money they add up to.
    exceptions = reconciliation_exceptions(accounts, transactions, transfers, ledger_entries)
    return exceptions.groupBy("kind").agg(
        F.count("*").alias("exceptions"),
        F.sum("amount").cast(MONEY).alias("amount"),
    )
